class Solution:
    def countPairs(self, nums: List[int], low: int, high: int) -> int:
        cnt = 0
        n = len(nums)
        for i in range(n):
            for j in range(i + 1, n):
                if low <= nums[i] ^ nums[j] <= high:
                    cnt += 1
        return cnt

