class Solution {
public:
    int countPairs(vector<int>& nums, int low, int high) {
        int cnt = 0;
        for (int i = 0; i < (int)nums.size(); ++i)
            for (int j = i + 1; j < (int)nums.size(); ++j) {
                int x = nums[i] ^ nums[j];
                if (low <= x && x <= high) ++cnt;
            }
        return cnt;
    }
};

