class Solution {
    struct Trie {
        vector<array<int, 2>> ch{{0, 0}};
        vector<int> cnt{0};

        void insert(int x) {
            int cur = 0;
            for (int i = 14; i >= 0; --i) {
                int b = (x >> i) & 1;
                if (!ch[cur][b]) {
                    ch.push_back({0, 0});
                    cnt.push_back(0);
                    ch[cur][b] = (int)ch.size() - 1;
                }
                cur = ch[cur][b];
                ++cnt[cur];
            }
        }

        long long countLE(int x, int k) {
            int cur = 0;
            long long res = 0;
            for (int i = 14; i >= 0; --i) {
                int b = (x >> i) & 1;
                if ((k >> i) & 1) {
                    res += cnt[ch[cur][b]];
                    cur = ch[cur][b ^ 1];
                } else {
                    cur = ch[cur][b];
                }
                if (!cur) return res;
            }
            return res + cnt[cur];
        }
    };

public:
    int countPairs(vector<int>& nums, int low, int high) {
        Trie t;
        long long ans = 0;
        for (int x : nums) {
            ans += t.countLE(x, high) - t.countLE(x, low - 1);
            t.insert(x);
        }
        return (int)ans;
    }
};

