class Solution {
    private int[][] ch;
    private int[] cnt;
    private int sz;

    public int countPairs(int[] nums, int low, int high) {
        ch = new int[nums.length * 15 + 1][2];
        cnt = new int[nums.length * 15 + 1];
        sz = 1;
        int ans = 0;
        for (int x : nums) {
            ans += countLE(x, high) - countLE(x, low - 1);
            insert(x);
        }
        return ans;
    }

    private void insert(int x) {
        int cur = 0;
        for (int i = 14; i >= 0; --i) {
            int b = (x >> i) & 1;
            if (ch[cur][b] == 0) ch[cur][b] = sz++;
            cur = ch[cur][b];
            ++cnt[cur];
        }
    }

    private int countLE(int x, int k) {
        int cur = 0, res = 0;
        for (int i = 14; i >= 0; --i) {
            int b = (x >> i) & 1;
            if (((k >> i) & 1) == 1) {
                res += cnt[ch[cur][b]];
                cur = ch[cur][b ^ 1];
            } else {
                cur = ch[cur][b];
            }
            if (cur == 0) return res;
        }
        return res + cnt[cur];
    }
}

